def find_sensor(grid):
    """Find the unique sensor row/column - a uniform row/col that appears only once"""
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    uniform_rows = {}
    uniform_cols = {}

    for r in range(rows):
        row = grid[r]
        val = row[0]
        if val > 0 and len(set(row)) == 1:
            uniform_rows.setdefault(val, []).append(r)

    for c in range(cols):
        col_values = [grid[r][c] for r in range(rows)]
        val = col_values[0]
        if val > 0 and len(set(col_values)) == 1:
            uniform_cols.setdefault(val, []).append(c)

    for val, r_indices in uniform_rows.items():
        if len(r_indices) == 1:
            return ('row', r_indices[0], val)

    for val, c_indices in uniform_cols.items():
        if len(c_indices) == 1:
            return ('col', c_indices[0], val)

    return None

def transform(grid):
    """Apply two-region sensor transformation"""
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    sensor = find_sensor(grid)
    if sensor is None:
        return grid

    sensor_type, sensor_idx, sensor_val = sensor
    offset = sensor_idx + 1

    if sensor_type == 'row':
        output_rows = sensor_idx
        output_cols = cols
    else:
        output_rows = rows
        output_cols = sensor_idx

    new_grid = []
    for r in range(output_rows):
        new_row = []
        for c in range(output_cols):
            if sensor_type == 'row':
                val1 = grid[r][c]
                val2 = grid[r + offset][c] if r + offset < rows else 0
            else:
                val1 = grid[r][c]
                val2 = grid[r][c + offset] if c + offset < cols else 0

            if val1 != 0 and val2 != 0:
                new_row.append(2)
            else:
                new_row.append(0)
        new_grid.append(new_row)

    return new_grid

