import json

def transform(grid):
    """
    ARC Transformation Rule:
    For each column, find the fill_row (uniform row filled with one value).
    If the special value appears in row 0 (first row) of that column:
        Change ALL occurrences of the special value in that column to 2.
    Otherwise (if special value not in row 0):
        Only change the special value in the fill_row to 2.
    """
    rows = len(grid)
    cols = len(grid[0])
    fill_row_idx = None

    for r in range(rows):
        row_filled = len(set(grid[r])) == 1 and grid[r][0] == 6
        if row_filled:
            fill_row_idx = r
            break

    output = [row[:] for row in grid]

    for c in range(cols):
        first_has_special = (grid[0][c] == 6)

        if first_has_special:
            for r in range(rows):
                if grid[r][c] == 6:
                    output[r][c] = 2
        else:
            if grid[fill_row_idx][c] == 6:
                output[fill_row_idx][c] = 2

    return output

